// Тратит награду. УБОРКА: подарок/сообщения не удаляются (cleanup); new02 отвечает — снимает «до ответа».
// Экран «למי לשלוח?» (/gift/recipient) — тексты из комментария программиста и скринов r10-fdc5b2-gift-*. Не проверен на живой странице.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { phone, openStreak, openPicker, chooseReward, claimButton } from './streak-helpers';
import { N2, U4, openChat, giftMessageField, freeSendButton, awaitingReplyHint } from '../gifts/gifts-helpers';

test.describe('Серия: награда «מתנה»', () => {
  test.describe.configure({ mode: 'serial', timeout: 240_000 });

  test('«מתנה»: «למי לשלוח?» (поиск, «לא נמצא אף אחד בשם הזה») → «QA П2 0011» → «שליחת מתנה • חינם» → чат с исходящей карточкой; new02 отвечает @iphone @data (#fdc5b2 #808adb #802740)', async ({ asUser }) => {
    const s = await asUser('user4');
    const r = await asUser('new02');
    const msg = `QA-AUTO streak gift ${Date.now()}`;
    let sent = false;
    let replied = false;
    try {
      await phone(s);
      await phone(r);
      await openStreak(s);
      await openPicker(s);
      await chooseReward(s, 'מתנה');
      await claimButton(s).click();

      // «למי לשלוח?»: поиск.
      await expect(s.getByText('למי לשלוח?')).toBeVisible({ timeout: 20_000 });
      const search = s.getByRole('textbox', { name: /חיפוש לפי שם/ }).or(s.getByPlaceholder('חיפוש לפי שם')).first();
      await search.fill('zzzqqq');
      await expect(s.getByText('לא נמצא אף אחד בשם הזה')).toBeVisible();
      await search.fill('QA П2');
      await s.getByText(N2, { exact: true }).first().click();

      // Экран отправки «• חינם».
      await expect(s.getByText('שליחת מתנה', { exact: true }).first()).toBeVisible();
      await expect(awaitingReplyHint(s, N2), 'ОКРУЖЕНИЕ: прошлый подарок user4→new02 без ответа — ответь вручную new02 → чат «QA רביעית»').toHaveCount(0);
      await expect(freeSendButton(s)).toBeEnabled();
      await giftMessageField(s).fill(msg);
      const w = s.waitForResponse((x) => x.url().includes('/rpc/send_gift') && x.request().method() === 'POST');
      await freeSendButton(s).click();
      const res = await w;
      expect(res.ok(), `send_gift: ${res.status()} ${await res.text()}`).toBeTruthy();
      sent = true;

      // Открылся чат «QA П2 0011» с исходящей карточкой.
      await expect(s.getByText(msg).last()).toBeVisible({ timeout: 30_000 });
      await expect(s.getByText(/שלחת מתנה/).last()).toBeVisible();

      // new02 отвечает.
      await openChat(r, U4);
      await expect(r.getByText(msg).last()).toBeVisible({ timeout: 30_000 });
      await r.getByRole('textbox', { name: 'כתוב הודעה' }).fill(`${msg} reply`);
      const w2 = r.waitForResponse((x) => x.url().includes('/rest/v1/messages') && x.request().method() === 'POST');
      await r.getByRole('button', { name: 'שליחה' }).click();
      expect((await w2).ok()).toBeTruthy();
      replied = true;
    } finally {
      if (sent) test.info().annotations.push({ type: 'cleanup', description: `user4: награда серии → подарок new02 «${msg}»${replied ? ' + ответ new02' : ''} — удалить нельзя` });
      if (sent && !replied) test.info().annotations.push({ type: 'cleanup', description: 'new02 НЕ ответил user4 — ответь вручную (new02 → чат «QA רביעית»)' });
      await saveSession(s, 'user4');
      await saveSession(r, 'new02');
    }
  });
});
